'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const { EventEmitter } = require('node:events');
const {
    LoeweClient, KEYS, TABLET_ACTIONS, buildEnvelope, buildKeyParameters,
    buildKeyboardParameters, createWolPacket, parseResponse, parseZapResult, ProtocolError,
} = require('../lib/loewe-client');
const { createDefinitions } = require('../lib/states');

// Golden request bodies copied from the APK 1.4.7 extraction, not generated by
// the client under test. The original access body is 501 bytes before NUL.
const ACCESS_XML = '<?xml version="1.0" encoding="UTF-8"?>\r\n<SOAP-ENV:Envelope xmlns:SOAP-ENV="http://schemas.xmlsoap.org/soap/envelope/" xmlns:SOAP-ENC="http://schemas.xmlsoap.org/soap/encoding/" xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" xmlns:xsd="http://www.w3.org/2001/XMLSchema" xmlns:ns1="urn:loewe.de:RemoteTV:Tablet"><SOAP-ENV:Body><ns1:RequestAccess xsi:type="ns1:RequestAccessRequestType"><fcid></fcid><DeviceType>----------------</DeviceType></ns1:RequestAccess></SOAP-ENV:Body></SOAP-ENV:Envelope>';
const OK_XML = '<?xml version="1.0" encoding="UTF-8"?>\r\n<SOAP-ENV:Envelope xmlns:SOAP-ENV="http://schemas.xmlsoap.org/soap/envelope/" xmlns:SOAP-ENC="http://schemas.xmlsoap.org/soap/encoding/" xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" xmlns:xsd="http://www.w3.org/2001/XMLSchema" xmlns:ns1="urn:loewe.de:RemoteTV:Tablet"><SOAP-ENV:Body><ns1:InjectRCKey><fcid></fcid><ClientId>CLIENT_ID_AUS_REQUEST_ACCESS</ClientId><InputEventSequence><RCKeyEvent alphabet="l2700" mode="press" value="38"/><RCKeyEvent alphabet="l2700" mode="release" value="38"/></InputEventSequence></ns1:InjectRCKey></SOAP-ENV:Body></SOAP-ENV:Envelope>';

// Synthetic TV replies exercise transport/parser behavior. They are not
// recorded replies from physical hardware.
function reply(action, inner = '') {
    return `<s:Envelope xmlns:s="http://schemas.xmlsoap.org/soap/envelope/" xmlns:m="urn:loewe.de:RemoteTV:Tablet"><s:Body><m:${action}Response>${inner}</m:${action}Response></s:Body></s:Envelope>`;
}

function fault(message) {
    return '<s:Envelope xmlns:s="http://schemas.xmlsoap.org/soap/envelope/">'
        + '<s:Body><s:Fault><faultcode>s:Client</faultcode>'
        + `<faultstring>${message}</faultstring></s:Fault></s:Body></s:Envelope>`;
}

function httpMock(scenarios) {
    const calls = [];
    return {
        calls,
        request(options, onResponse) {
            const request = new EventEmitter();
            const call = { options, request, body: null };
            request.destroyed = false;
            request.destroy = () => { request.destroyed = true; };
            call.reply = spec => {
                if (request.destroyed) {
                    return;
                }
                const plan = typeof spec === 'string' ? { xml: spec } : spec;
                if (plan.error) {
                    request.emit('error', plan.error);
                    return;
                }
                const response = new EventEmitter();
                response.statusCode = plan.status ?? 200;
                response.headers = plan.headers || {};
                response.destroyed = false;
                response.destroy = () => { response.destroyed = true; };
                call.response = response;
                onResponse(response);
                if (plan.aborted) {
                    response.emit('aborted');
                    return;
                }
                for (const chunk of plan.chunks || [Buffer.from(plan.xml || '')]) {
                    if (!response.destroyed) {
                        response.emit('data', chunk);
                    }
                }
                if (!response.destroyed) {
                    response.emit('end');
                }
            };
            request.end = body => {
                call.body = body;
                calls.push(call);
                const spec = scenarios.shift();
                if (spec !== null && spec !== undefined) {
                    queueMicrotask(() => call.reply(spec));
                }
            };
            return request;
        },
    };
}

function clientFor(scenarios, options = {}) {
    const transport = httpMock(scenarios);
    const client = new LoeweClient({ host: 'tv.example', timeout: 1000, ...options }, transport);
    return { client, transport };
}

function access(id = '00123') {
    return reply('RequestAccess', `<m:ClientId>${id}</m:ClientId>`);
}

function commandName(call) {
    return call.options.headers.SOAPAction.split('#')[1].replace(/"$/, '');
}

test('golden APK access/OK XML, 33 actions and verified remote alphabets', () => {
    assert.equal(buildEnvelope('RequestAccess'), ACCESS_XML);
    assert.equal(Buffer.byteLength(ACCESS_XML), 501);
    assert.equal(buildEnvelope('InjectRCKey', buildKeyParameters('ok'), 'CLIENT_ID_AUS_REQUEST_ACCESS'), OK_XML);
    assert.equal(TABLET_ACTIONS.length, 33);
    assert.equal(new Set(TABLET_ACTIONS).size, 33);
    assert.equal(Object.keys(KEYS).length, 44); // 40 APK keys plus TV_ON, TV_MODE_ON, DR_ARCHIVE and BACK from the API.
    assert.equal(KEYS.radio_mode_on, undefined);
    assert.throws(() => buildKeyParameters('radio_mode_on'), { code: 'VALIDATION' });
    assert.deepEqual(KEYS.tv_mode_on, { alphabet: 'l2700', value: 72 });
    assert.deepEqual(KEYS.power_on, { alphabet: 'l2700', value: 22 });
    assert.equal(buildKeyParameters('power_on'), '<InputEventSequence>'
        + '<RCKeyEvent alphabet="l2700" mode="press" value="22"/>'
        + '<RCKeyEvent alphabet="l2700" mode="release" value="22"/></InputEventSequence>');
    assert.deepEqual(KEYS.left, { alphabet: 'l2700', value: 17 });
    assert.deepEqual(KEYS.right, { alphabet: 'l2700', value: 16 });
    assert.deepEqual(KEYS.play, { alphabet: 'l2700-hdr', value: 53 });
    assert.deepEqual(KEYS.power_all_code, { alphabet: 'l2700', value: 25 });
    assert.deepEqual(KEYS.epg, { alphabet: 'l2700', value: 15 });
    assert.deepEqual(KEYS.epg_alt, { alphabet: 'l2700', value: 78 });
    for (let digit = 0; digit <= 9; digit++) {
        assert.deepEqual(KEYS[`digit_${digit}`], { alphabet: 'l2700', value: digit });
    }
    assert.match(buildEnvelope('GetDeviceData', '', 'abc'), /GetDeviceData xsi:type="ns1:ClientRequestType"/);
    assert.doesNotMatch(buildEnvelope('GetVolume', '', 'abc'), /GetVolume xsi:type=/);
});

test('documented DR+ archive key sends one press/release pair and has a writable button state', async t => {
    // Loewe Remote API 1.0.47, section 9.4.1.1, p. 25: DR_ARCHIVE = l2700/92.
    // Section 9.4.1 requires a release event; this is a short key press.
    const parameters = '<InputEventSequence>'
        + '<RCKeyEvent alphabet="l2700" mode="press" value="92"/>'
        + '<RCKeyEvent alphabet="l2700" mode="release" value="92"/></InputEventSequence>';
    assert.deepEqual(KEYS.dr_archive, { alphabet: 'l2700', value: 92 });
    assert.equal(buildKeyParameters('dr_archive'), parameters);
    const { client, transport } = clientFor([access('dr-fixture'), reply('InjectRCKey')]);
    t.after(() => client.close());
    await client.key('dr_archive');
    assert.equal(transport.calls.length, 2);
    assert.equal(commandName(transport.calls[1]), 'InjectRCKey');
    assert.equal(transport.calls[1].body.toString('utf8'),
        buildEnvelope('InjectRCKey', parameters, 'dr-fixture') + '\0');
    const definition = createDefinitions({ maxVolume: 100 }).find(item => item.id === 'remote.dr_archive');
    assert.equal(definition.type, 'state');
    assert.deepEqual(definition.common.name, { en: 'Open DR+ archive', de: 'DR+-Archiv öffnen' });
    assert.equal(definition.common.type, 'boolean');
    assert.equal(definition.common.role, 'button');
    assert.equal(definition.common.read, false);
    assert.equal(definition.common.write, true);
});

test('the historical power key names preserve distinct documented toggle and off codes', () => {
    // Loewe Remote API 1.0.47, section 9.4.1.1, pp. 24-25: ON_OFF=12, TV_OFF=25.
    assert.deepEqual(KEYS.power_off, { alphabet: 'l2700', value: 12 });
    assert.equal(buildKeyParameters('power_all_code'), '<InputEventSequence>'
        + '<RCKeyEvent alphabet="l2700" mode="press" value="25"/>'
        + '<RCKeyEvent alphabet="l2700" mode="release" value="25"/></InputEventSequence>');
});

test('documented BACK is separate from the established END mapping', () => {
    // Loewe Remote API 1.0.47, section 9.4.1.1, p. 25: END=63 and BACK=65.
    assert.deepEqual(KEYS.back, { alphabet: 'l2700', value: 63 });
    assert.deepEqual(KEYS.back_step, { alphabet: 'l2700', value: 65 });
    assert.equal(buildKeyParameters('back_step'), '<InputEventSequence>'
        + '<RCKeyEvent alphabet="l2700" mode="press" value="65"/>'
        + '<RCKeyEvent alphabet="l2700" mode="release" value="65"/></InputEventSequence>');
    const definition = createDefinitions({ maxVolume: 100 }).find(item => item.id === 'remote.back_step');
    assert.equal(definition.common.name.de, 'Zurück (BACK)');
    assert.equal(definition.common.role, 'button');
    assert.equal(definition.common.write, true);
});

test('ZapToMedia result parsing preserves rejection codes and empty-response compatibility', async t => {
    const samples = [
        ['<Result>0</Result>', 0], ['<m:Result type="int"> -1 </m:Result>', -1],
        ['<Result>17</Result>', 17], ['', null], ['<fcid/><ClientId>tv-fixture</ClientId>', null],
    ];
    const { client } = clientFor([access('tv-fixture'), ...samples.map(([inner]) => reply('ZapToMedia', inner))]);
    t.after(() => client.close());
    for (const [inner, result] of samples) {
        const response = await client.zap('channel://1:ch-tv:sl-list');
        assert.equal(response.xml, reply('ZapToMedia', inner), 'Retain rejected TV replies for diagnostics.');
        assert.equal(parseZapResult(response), result);
    }
});

test('ZapToMedia rejects malformed results and responses from unrelated actions', () => {
    for (const inner of [
        '<Result/>', '<Result>OK</Result>', '<Result>1.5</Result>', '<Result>NaN</Result>',
        '<Result>0x0</Result>', '<Result>1e3</Result>', '<Result>9007199254740992</Result>',
        '<Result>0</Result><Result>0</Result>', '<Result>0<Extra/></Result>', '<Result><value>0</value></Result>',
    ]) {
        assert.throws(() => parseZapResult(parseResponse(reply('ZapToMedia', inner))), { code: 'INVALID_RESPONSE' }, inner);
    }
    const envelope = body => '<s:Envelope xmlns:s="http://schemas.xmlsoap.org/soap/envelope/">'
        + `<s:Body>${body}</s:Body></s:Envelope>`;
    assert.equal(parseZapResult(parseResponse(envelope('<ZapToMediaResponse/>'))), null);
    for (const xml of [
        reply('GetDeviceData', '<Result>0</Result>'),
        envelope('<ZapToMediaResponse/><ZapToMediaResponse/>'),
        envelope('<ZapToMediaResponse/><GetDeviceDataResponse/>'),
    ]) {
        assert.throws(() => parseZapResult(parseResponse(xml)), { code: 'INVALID_RESPONSE', action: 'ZapToMedia' });
    }
});

test('invalid actions and injected/malformed XML are rejected before any network access', async () => {
    const { client, transport } = clientFor([]);
    for (const [action, parameters] of [
        ['DeleteEverything', ''], ['GetVolume\r\nBad:header', ''],
        ['GetVolume', '<Value>1'], ['GetVolume', '</Parameters><evil/>'],
        ['GetVolume', '<ClientId>other</ClientId>'], ['GetVolume', '<ns1:fcid>other</ns1:fcid>'],
        ['GetVolume', '<!DOCTYPE p [<!ENTITY e "test">]><Value>&e;</Value>'],
        ['GetVolume', '<Value>\0</Value>'], ['GetVolume', '<Value>&#0;</Value>'],
        ['GetVolume', '<?xml version="1.0"?><Value>1</Value>'],
        ['GetVolume', '<Value>&unknown;</Value>'],
        ['GetVolume', '<Value first="1" first="2"/>'],
        ['GetVolume', '<Value xmlns:x="urn:same" xmlns:y="urn:same" x:id="1" y:id="2"/>'],
        ['RequestAccess', '<DeviceType>changed</DeviceType>'],
    ]) {
        await assert.rejects(client.request(action, parameters), { code: 'VALIDATION' });
    }
    assert.throws(() => buildKeyParameters('toString'), { code: 'VALIDATION' });
    assert.throws(() => buildKeyboardParameters(0xd800), { code: 'VALIDATION' });
    assert.throws(() => buildKeyboardParameters(14, 'shift'), { code: 'VALIDATION' });
    assert.equal(transport.calls.length, 0);
    client.close();
});

test('response parser preserves namespaces-free string identifiers, attributes and Unicode', () => {
    const result = parseResponse(Buffer.from(reply('GetDeviceData',
        '<m:Serial index="0004">000123</m:Serial><m:Name>  Gästezimmer &amp; Küche  </m:Name>') + '\0'));
    assert.deepEqual(result.data.Envelope.Body.GetDeviceDataResponse.Serial, {
        '#text': '000123', '@_index': '0004',
    });
    assert.equal(result.data.Envelope.Body.GetDeviceDataResponse.Name, '  Gästezimmer & Küche  ');
    assert.equal(result.xml.endsWith('\0'), false);
    assert.throws(() => parseResponse('<html>unrelated</html>'), { code: 'INVALID_RESPONSE' });
    assert.throws(() => parseResponse(Buffer.from([0xff, 0xfe])), { code: 'INVALID_RESPONSE' });
    assert.throws(() => parseResponse(reply('GetMute', '<Value>1')), { code: 'INVALID_RESPONSE' });
});

test('XML nesting is bounded and unbound namespace prefixes or multiple roots are rejected', () => {
    const deep = '<Node>'.repeat(129) + 'x' + '</Node>'.repeat(129);
    assert.throws(() => buildEnvelope('GetFeature', deep), { code: 'VALIDATION' });
    assert.throws(() => parseResponse(reply('GetFeature', deep)), { code: 'INVALID_RESPONSE' });
    assert.throws(() => buildEnvelope('GetFeature', '<missing:Name>x</missing:Name>'), { code: 'VALIDATION' });
    assert.throws(() => parseResponse(reply('GetMute') + '<Other/>'), { code: 'INVALID_RESPONSE' });
});

test('XML element/attribute names cannot change object prototypes', () => {
    const { data } = parseResponse(reply('GetDeviceData',
        '<__proto__><polluted>yes</polluted></__proto__><Item __proto__="safe"/>'));
    const properties = data.Envelope.Body.GetDeviceDataResponse;
    assert.equal(Object.getPrototypeOf(properties), Object.prototype);
    assert.equal(Object.hasOwn(properties, '__proto__'), true);
    assert.equal(properties.__proto__.polluted, 'yes');
    assert.equal(properties.Item['@___proto__'], 'safe');
    assert.equal({}.polluted, undefined);
});

test('HTTP handshake sends exact endpoint, SOAP header, final NUL and UTF-8 byte lengths', async () => {
    const { client, transport } = clientFor([
        access('00077'), reply('GetVolume', '<m:Value>250000</m:Value>'), reply('GetFeature'),
    ]);
    assert.equal(client.isSessionReady, false);
    assert.equal(await client.getVolume(), 25);
    assert.equal(client.isSessionReady, true);
    await client.request('GetFeature', '<Name>Größe &amp; Qualität</Name>');
    assert.equal(transport.calls.length, 3);
    assert.equal(transport.calls[0].body.toString('utf8'), ACCESS_XML + '\0');
    for (const call of transport.calls) {
        assert.equal(call.options.hostname, 'tv.example');
        assert.equal(call.options.port, 905);
        assert.equal(call.options.method, 'POST');
        assert.equal(call.options.path, '/loewe_tablet_0001');
        assert.equal(call.options.headers['Content-Type'], 'text/xml; charset=utf-8');
        assert.equal(call.options.headers['User-Agent'], 'LOEWE SOAP/1.0');
        assert.equal(call.options.headers.Connection, 'close');
        assert.equal(call.options.headers['Content-Length'], call.body.length);
        assert.equal(call.body.at(-1), 0);
        assert.match(call.options.headers.SOAPAction, /^"urn:loewe\.de:RemoteTV:Tablet#/);
    }
    assert.match(transport.calls[1].body.toString('utf8'), /<ClientId>00077<\/ClientId>/);
    assert.notEqual(transport.calls[2].body.length, transport.calls[2].body.toString('utf8').length);
    client.close();
});

test('appendNul=false is honored independently of multibyte parameter text', async () => {
    const { client, transport } = clientFor([access(), reply('GetFeature')], { appendNul: false });
    await client.request('GetFeature', '<Name>Ä</Name>');
    for (const call of transport.calls) {
        assert.equal(call.body.at(-1), 62);
        assert.equal(call.options.headers['Content-Length'], call.body.length);
    }
    assert.equal(transport.calls[0].body.length, 501);
    client.close();
});

test('simultaneous first calls share one handshake and use the returned ClientId', async () => {
    const { client, transport } = clientFor([
        null, reply('GetVolume', '<m:Value>300000</m:Value>'), reply('GetMute', '<m:Value>1</m:Value>'),
    ]);
    const volume = client.getVolume();
    const mute = client.getMute();
    assert.equal(transport.calls.length, 1);
    transport.calls[0].reply(access('00099'));
    assert.deepEqual(await Promise.all([volume, mute]), [30, true]);
    assert.deepEqual(transport.calls.map(commandName), ['RequestAccess', 'GetVolume', 'GetMute']);
    assert.match(transport.calls[2].body.toString(), /<ClientId>00099<\/ClientId>/);
    client.close();
});

test('missing ClientId stops the original operation and permits a fresh later handshake', async () => {
    const { client, transport } = clientFor([
        reply('RequestAccess'), access(), reply('InjectRCKey'),
    ]);
    await assert.rejects(client.key('ok'), { code: 'INVALID_RESPONSE' });
    assert.equal(client.isSessionReady, false);
    assert.equal(transport.calls.length, 1);
    await client.key('ok');
    assert.deepEqual(transport.calls.map(commandName), ['RequestAccess', 'RequestAccess', 'InjectRCKey']);
    client.close();
});

test('volume scales sends exactly and keeps response values without silent clamping', async () => {
    const { client, transport } = clientFor([
        access(), reply('SetVolume'), reply('SetVolume'),
        reply('GetVolume', '<Value>1000000</Value>'), reply('GetVolume', '<Value>250001</Value>'),
    ]);
    for (const invalid of [-1, 100, 12.5, NaN, Infinity, '20', null]) {
        await assert.rejects(client.setVolume(invalid), { code: 'VALIDATION' });
    }
    assert.equal(transport.calls.length, 0);
    await client.setVolume(0);
    await client.setVolume(99);
    assert.match(transport.calls[1].body.toString(), /<Value>0<\/Value>/);
    assert.match(transport.calls[2].body.toString(), /<Value>990000<\/Value>/);
    assert.equal(await client.getVolume(), 100);
    assert.equal(await client.getVolume(), 25.0001);
    client.close();
});

test('malformed/missing/ambiguous numeric and mute replies are not turned into state values', async () => {
    const { client } = clientFor([
        access(),
        ...['', '-1', 'NaN', '100.2', '9007199254740993'].map(value => reply('GetVolume', `<Value>${value}</Value>`)),
        reply('GetVolume', '<Value>10000</Value><Value>20000</Value>'),
        reply('GetMute', '<Value>true</Value>'), reply('GetMute'),
        reply('GetMute', '<Value>0</Value>'), reply('GetMute', '<Value>1</Value>'),
    ]);
    for (let i = 0; i < 6; i++) {
        await assert.rejects(client.getVolume(), { code: 'INVALID_RESPONSE' });
    }
    await assert.rejects(client.getMute(), { code: 'INVALID_RESPONSE' });
    await assert.rejects(client.getMute(), { code: 'INVALID_RESPONSE' });
    assert.equal(await client.getMute(), false);
    assert.equal(await client.getMute(), true);
    client.close();
});

test('mute uses numeric 1/0 and validates booleans before contact', async () => {
    const { client, transport } = clientFor([access(), reply('SetMute'), reply('SetMute')]);
    await assert.rejects(client.setMute('false'), { code: 'VALIDATION' });
    assert.equal(transport.calls.length, 0);
    await client.setMute(true);
    await client.setMute(false);
    assert.match(transport.calls[1].body.toString(), /<Value>1<\/Value>/);
    assert.match(transport.calls[2].body.toString(), /<Value>0<\/Value>/);
    client.close();
});

test('text iterates Unicode code points and backspace uses scancode 14', async () => {
    const { client, transport } = clientFor([
        access(), reply('InjectKeyboardKey'), reply('InjectKeyboardKey'), reply('InjectKeyboardKey'),
    ]);
    await assert.rejects(client.text('A\ud800B'), { code: 'VALIDATION' });
    assert.equal(transport.calls.length, 0);
    await client.text('Ä💡');
    await client.backspace();
    assert.equal(transport.calls.length, 4);
    assert.match(transport.calls[1].body.toString(), /mode="press" modifiers="" value="196"/);
    assert.match(transport.calls[2].body.toString(), /mode="press" modifiers="" value="128161"/);
    assert.match(transport.calls[2].body.toString(), /mode="release" modifiers="" value="128161"/);
    assert.match(transport.calls[3].body.toString(), /mode="press" modifiers="scancode" value="14"/);
    assert.equal(await client.text(''), null);
    assert.equal(transport.calls.length, 4);
    client.close();
});

test('text stops on first failed character without replaying accepted characters', async () => {
    const { client, transport } = clientFor([
        access(), reply('InjectKeyboardKey'), { status: 500, xml: fault('Keyboard unavailable') },
    ]);
    await assert.rejects(client.text('ABC'), { code: 'SOAP' });
    assert.equal(transport.calls.length, 3);
    assert.match(transport.calls[1].body.toString(), /value="65"/);
    assert.match(transport.calls[2].body.toString(), /value="66"/);
    client.close();
});

test('queries and ZapToMedia use extracted range/order fields and safely escaped identifiers', async () => {
    const { client, transport } = clientFor([
        access(), reply('GetListOfChannelLists'), reply('GetChannelList'), reply('ZapToMedia'),
        reply('GetSettings'), reply('GetCurrentPlayback'), reply('GetDeviceData'),
    ]);
    await client.getChannelLists(5, 20);
    await client.getChannels('TV & Radio', 10, 50);
    await client.zap('dvb://a?title=<Test>&id=3');
    await client.getSettings();
    await client.getCurrentPlayback();
    await client.getDeviceData();
    assert.match(transport.calls[1].body.toString(), /<Range startIndex="5" maxItems="20"\/>/);
    assert.match(transport.calls[2].body.toString(), /<ChannelListView>TV &amp; Radio<\/ChannelListView>/);
    assert.match(transport.calls[2].body.toString(), /<OrderField field="userChannelNumber" type="ascending"\/>/);
    assert.match(transport.calls[2].body.toString(), /<MediaItemInformation>true<\/MediaItemInformation><MediaItemClass>video<\/MediaItemClass>/);
    assert.match(transport.calls[3].body.toString(), /<Player>0<\/Player><Locator>dvb:\/\/a\?title=&lt;Test&gt;&amp;id=3<\/Locator>/);
    assert.throws(() => client.getChannelLists(-1, 20), { code: 'VALIDATION' });
    assert.throws(() => client.getChannels('view', 0, 0), { code: 'VALIDATION' });
    client.close();
});

test('SOAP errors are distinguished from HTTP failures and reset only invalid sessions', async () => {
    const { client, transport } = clientFor([
        access('first'), { status: 500, xml: fault('Unsupported action') },
        { status: 500, xml: fault('Invalid ClientId') },
        access('second'), reply('GetMute', '<Value>0</Value>'), { status: 401, xml: 'Access denied' },
    ]);
    await assert.rejects(client.getSettings(), error => error instanceof ProtocolError
        && error.code === 'SOAP' && error.httpStatus === 500 && !error.sessionInvalid);
    assert.equal(client.isSessionReady, true);
    await assert.rejects(client.key('ok'), error => error.code === 'SOAP' && error.sessionInvalid);
    assert.equal(client.isSessionReady, false);
    assert.equal(transport.calls.length, 3);
    assert.equal(await client.getMute(), false);
    assert.equal(client.isSessionReady, true);
    await assert.rejects(client.getSettings(), { code: 'HTTP', httpStatus: 401 });
    assert.equal(client.isSessionReady, false);
    assert.deepEqual(transport.calls.map(commandName), [
        'RequestAccess', 'GetSettings', 'InjectRCKey', 'RequestAccess', 'GetMute', 'GetSettings',
    ]);
    client.close();
});

test('total timeout aborts a mutation without retry; a later command gets a fresh session', async () => {
    const { client, transport } = clientFor([
        access(), null, access('new'), reply('GetMute', '<Value>0</Value>'),
    ], { timeout: 20 });
    await assert.rejects(client.key('volume_up'), { code: 'NETWORK', transportCode: 'ETIMEDOUT' });
    assert.equal(transport.calls.length, 2);
    assert.equal(transport.calls[1].request.destroyed, true);
    assert.equal(client.isSessionReady, false);
    assert.equal(await client.getMute(), false);
    assert.equal(transport.calls.filter(call => commandName(call) === 'InjectRCKey').length, 1);
    assert.equal(transport.calls.filter(call => commandName(call) === 'RequestAccess').length, 2);
    client.close();
});

test('network connection errors and truncated replies reject instead of succeeding', async () => {
    const { client, transport } = clientFor([
        { error: Object.assign(new Error('connect'), { code: 'ECONNREFUSED' }) },
        access(), { aborted: true },
    ]);
    await assert.rejects(client.key('ok'), { code: 'NETWORK', transportCode: 'ECONNREFUSED' });
    assert.equal(client.isSessionReady, false);
    await assert.rejects(client.getMute(), { code: 'NETWORK' });
    assert.equal(client.isSessionReady, false);
    assert.equal(transport.calls.length, 3);
    client.close();
});

test('advertised and streamed response sizes are bounded before parsing', async () => {
    const { client, transport } = clientFor([
        { headers: { 'content-length': '8388609' }, xml: access() },
        { chunks: [Buffer.alloc(8388608, 0x20), Buffer.from('x')] },
    ]);
    await assert.rejects(client.getVolume(), { code: 'INVALID_RESPONSE' });
    assert.equal(transport.calls[0].response.destroyed, true);
    await assert.rejects(client.getVolume(), { code: 'INVALID_RESPONSE' });
    assert.equal(transport.calls[1].response.destroyed, true);
    client.close();
});

test('close aborts pending requests, prevents all later actions and ignores late handshake data', async () => {
    const { client, transport } = clientFor([null]);
    const operation = client.key('power_off');
    const rejection = assert.rejects(operation, { code: 'CLOSED' });
    client.close();
    await rejection;
    transport.calls[0].reply(access('late'));
    assert.equal(client.isSessionReady, false);
    assert.equal(transport.calls[0].request.destroyed, true);
    await assert.rejects(client.request('GetVolume'), { code: 'CLOSED' });
    await assert.rejects(client.text(''), { code: 'CLOSED' });
    await assert.rejects(client.wake('02:00:00:00:00:01'), { code: 'CLOSED' });
    assert.equal(transport.calls.length, 1);
    client.close();
});

test('Wake-on-LAN packet is exactly six FF bytes and sixteen repetitions of the TV MAC', () => {
    const packet = createWolPacket('02:1a:2b:3c:4d:5e');
    assert.equal(packet.length, 102);
    assert.deepEqual(packet.subarray(0, 6), Buffer.alloc(6, 0xff));
    for (let offset = 6; offset < 102; offset += 6) {
        assert.equal(packet.subarray(offset, offset + 6).toString('hex'), '021a2b3c4d5e');
    }
    assert.throws(() => createWolPacket('not-a-mac'), { code: 'VALIDATION' });
});

function udpMock(hang = false) {
    const sockets = [];
    return {
        sockets,
        createSocket(type) {
            const socket = new EventEmitter();
            socket.type = type;
            socket.sent = [];
            socket.closed = false;
            socket.bind = (port, host, callback) => {
                socket.bindArgs = [port, host];
                queueMicrotask(callback);
            };
            socket.setBroadcast = enabled => { socket.broadcastEnabled = enabled; };
            socket.send = (packet, offset, length, port, address, callback) => {
                socket.sent.push({ packet: Buffer.from(packet), offset, length, port, address });
                if (!hang) {
                    queueMicrotask(() => callback());
                }
            };
            socket.close = () => { socket.closed = true; };
            sockets.push(socket);
            return socket;
        },
    };
}

test('Wake-on-LAN validates all inputs, skips blanks/duplicates and uses broadcast UDP port 9', async () => {
    const transport = udpMock();
    const client = new LoeweClient({ host: 'tv.example' }, transport);
    await assert.rejects(client.wake(['', '  ']), { code: 'VALIDATION' });
    await assert.rejects(client.wake(['02:00:00:00:00:01', 'bad']), { code: 'VALIDATION' });
    await assert.rejects(client.wake('02:00:00:00:00:01', '300.0.0.1'), { code: 'VALIDATION' });
    assert.equal(transport.sockets.length, 0);
    const result = await client.wake(['02:aa:00:00:00:01', '', '02-AA-00-00-00-01', '02:00:00:00:00:02'], '192.168.178.255');
    assert.equal(transport.sockets.length, 1);
    const socket = transport.sockets[0];
    assert.equal(socket.type, 'udp4');
    assert.equal(socket.broadcastEnabled, true);
    assert.equal(socket.sent.length, 2);
    assert.deepEqual(result.macs, ['02:AA:00:00:00:01', '02:00:00:00:00:02']);
    assert.equal(socket.closed, true);
    for (const call of socket.sent) {
        assert.equal(call.port, 9);
        assert.equal(call.address, '192.168.178.255');
        assert.equal(call.length, 102);
    }
    assert.equal(client.isSessionReady, false);
    client.close();
});

test('close also cancels an in-flight Wake-on-LAN send and closes its socket', async () => {
    const transport = udpMock(true);
    const client = new LoeweClient({ host: 'tv.example' }, transport);
    const operation = client.wake('02:00:00:00:00:01');
    const rejection = assert.rejects(operation, { code: 'CLOSED' });
    await Promise.resolve();
    client.close();
    await rejection;
    assert.equal(transport.sockets[0].closed, true);
});
